let jadwalListenerActive=false;

function startJadwalListener(){
  if(jadwalListenerActive||!currentAuthUser)return;
  jadwalListenerActive=true;

  jadwalDb.on("value",async snapshot=>{
    const value=snapshot.val();

    if(!value){
      const seed={};
      DEFAULT_JADWAL_TOGEL.forEach(item=>{
        seed[item.id]={...item,updatedAt:Date.now(),updatedBy:"system"};
      });

      try{
        await jadwalDb.set(seed);
      }catch(error){
        console.error(error);
        showToast("Gagal membuat data awal jadwal");
      }
      return;
    }

    jadwalTogelData=Object.values(value).sort((a,b)=>
      Number(a.order||0)-Number(b.order||0)
    );
    renderJadwalTogel();
    if(typeof prediksiRender==="function")prediksiRender();
    if(typeof prediksiUpdateClock==="function")prediksiUpdateClock();
  },error=>{
    console.error(error);
    jadwalListenerActive=false;
    showToast("Gagal memuat Jadwal Togel");
  });
}

function stopJadwalListener(){
  jadwalDb.off();
  jadwalListenerActive=false;
  jadwalTogelData=DEFAULT_JADWAL_TOGEL.map(item=>({...item}));
  renderJadwalTogel();
  if(typeof prediksiRender==="function")prediksiRender();
  if(typeof prediksiUpdateClock==="function")prediksiUpdateClock();
}

