function makePermissions(enabledKeys=[]){
  const enabled=new Set(enabledKeys);
  return Object.fromEntries(ALL_MENU_KEYS.map(key=>[key,enabled.has(key)]));
}

const ROLE_PERMISSION_PRESETS = {
  /* CHAT dibuat terkunci untuk semua role biasa.
     Owner/Leader bisa mengizinkan manual dari Manajemen User dengan mencentang CHAT lalu Simpan Akses. */
  kasir:makePermissions([]),
  "kapten-kasir":makePermissions([]),

  "cs-livechat":makePermissions([
    "dashboard","pk-cs","gambar","prediksi-togel","jadwal-togel","notepad"
  ]),

  "cs-line":makePermissions([
    "dashboard","pk-cs","gambar","prediksi-togel","jadwal-togel","notepad",
    "prediksi","syair-togel","bukti-kemenangan","link-domain"
  ]),

  leader:makePermissions(ALL_MENU_KEYS),
  owner:makePermissions(ALL_MENU_KEYS)
};

function normalizeRole(role){
  const value=String(role||"").toLowerCase().trim();
  const legacyMap={
    staff:"cs-livechat",
    cs:"cs-livechat",
    livechat:"cs-livechat",
    kasir:"kasir",
    "kapten kasir":"kapten-kasir",
    "kapten-kasir":"kapten-kasir",
    "cs livechat":"cs-livechat",
    "cs-livechat":"cs-livechat",
    "cs line":"cs-line",
    "cs-line":"cs-line",
    leader:"leader",
    owner:"owner"
  };
  return legacyMap[value]||"cs-livechat";
}

function isFullAccessRole(role){
  const normalized=normalizeRole(role);
  return normalized==="owner"||normalized==="leader";
}

function permissionsForRole(role){
  const normalized=normalizeRole(role);
  return {...(ROLE_PERMISSION_PRESETS[normalized]||ROLE_PERMISSION_PRESETS["cs-livechat"])};
}

function collectPermissionsFromCard(card, role){
  const normalized=normalizeRole(role);
  if(isFullAccessRole(normalized)) return permissionsForRole(normalized);
  const permissions=makePermissions([]);
  card.querySelectorAll("[data-permission]").forEach(cb=>{
    permissions[cb.dataset.permission]=cb.checked===true;
  });
  return permissions;
}

function lockChatByDefault(profile){
  if(!profile) return profile;
  const role=normalizeRole(profile.role);
  if(isFullAccessRole(role)) return profile;
  const permissions={...permissionsForRole(role),...(profile.permissions||{})};
  if(profile.chatAccessManual!==true) permissions.chat=false;
  return {...profile,role,permissions};
}

