loginForm?.addEventListener("submit",async e=>{
  e.preventDefault();
  setAuthMessage("Memeriksa akun...");
  try{
    await auth.setPersistence(firebase.auth.Auth.Persistence.LOCAL);
    await auth.signInWithEmailAndPassword(
      document.getElementById("loginEmail").value.trim(),
      document.getElementById("loginPassword").value
    );
    setAuthMessage("Login berhasil.",true);
  }catch(error){setAuthMessage(authErrorText(error))}
});

registerForm?.addEventListener("submit",async e=>{
  e.preventDefault();

  const name=document.getElementById("registerName").value.trim();
  const email=document.getElementById("registerEmail").value.trim().toLowerCase();
  const password=document.getElementById("registerPassword").value;
  const confirmPassword=document.getElementById("registerPasswordConfirm").value;

  if(password!==confirmPassword){
    return setAuthMessage("Konfirmasi password tidak sama.");
  }

  setAuthMessage("Mendaftarkan akun...");

  try{
    const credential=await registerAuth.createUserWithEmailAndPassword(email,password);
    const isOwner=email===OWNER_EMAIL;

    const profile={
      uid:credential.user.uid,
      name,
      email,
      role:isOwner?"owner":"cs-livechat",
      status:"active",
      permissions:isOwner
        ? Object.fromEntries(ALL_MENU_KEYS.map(k=>[k,true]))
        : permissionsForRole("cs-livechat"),
      chatAccessManual:isOwner,
      createdAt:firebase.database.ServerValue.TIMESTAMP,
      updatedAt:firebase.database.ServerValue.TIMESTAMP
    };

    await registerDb.child(credential.user.uid).set(profile);
    await credential.user.updateProfile({displayName:name});

    /* Logout hanya pada auth registrasi sekunder, bukan auth utama */
    await registerAuth.signOut();

    registerForm.reset();

    document.querySelectorAll(".auth-tab").forEach(x=>{
      x.classList.toggle("active",x.dataset.authTab==="login");
    });

    loginForm.classList.add("active");
    registerForm.classList.remove("active");

    document.getElementById("loginEmail").value=email;
    document.getElementById("loginPassword").value="";

    setAuthMessage(
      isOwner
        ? "Akun Owner berhasil dibuat. Silakan login."
        : "Akun CS Livechat berhasil dibuat. Silakan login.",
      true
    );

    setTimeout(()=>document.getElementById("loginPassword")?.focus(),100);
  }catch(error){
    setAuthMessage(authErrorText(error));
  }
});

