    async function checkDomainsNawala(domains){
      const cleanDomains=[...new Set((domains||[]).map(normalizeDomain).filter(Boolean))];
      if(!cleanDomains.length) return [];

      const response=await fetch("https://trustpositif.id/api/v1/check",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({domains:cleanDomains.join("\n")})
      });

      let data={};
      try{data=await response.json()}catch(e){}
      if(!response.ok || !data.success){
        const message=data.message||data.error||`HTTP ${response.status}`;
        throw new Error(message);
      }
      return Array.isArray(data.results)?data.results:[];
    }

