    const pkCsDb=firebase.database().ref("pkCsKerjaBoss");
    let pkcsMigrating=false;
    function pkcsLocalBackup(){
      try{localStorage.setItem(PKCS_STORAGE_KEY,JSON.stringify(pkcsData))}catch(e){console.warn("Backup lokal PK gagal",e)}
    }
    function pkcsReadLocal(){
      try{
        const saved=JSON.parse(localStorage.getItem(PKCS_STORAGE_KEY)||"null");
        return Array.isArray(saved)&&saved.length?saved:null;
      }catch(e){return null}
    }
    function pkcsLoad(){
      pkCsDb.on("value",async snapshot=>{
        const data=snapshot.val()||{};
        const firebaseItems=Object.values(data);
        if(!firebaseItems.length&&!pkcsMigrating){
          pkcsMigrating=true;
          const source=pkcsReadLocal()||pkcsDefaults;
          const updates={};
          source.forEach((item,index)=>{
            const id=String(item.id||(`pk_${Date.now()}_${index}`));
            updates[id]={...item,id,updatedAt:item.updatedAt||Date.now()-index};
          });
          try{
            await pkCsDb.update(updates);
            showToast(pkcsReadLocal()?"Data PK lama dipindahkan ke Firebase":"Data awal PK disimpan ke Firebase");
          }catch(error){
            console.error(error);
            pkcsData=source;
            pkcsSelectedId=null;
            pkcsRender(false);
            showToast("Gagal menghubungkan PK CS ke Firebase");
          }finally{pkcsMigrating=false}
          return;
        }
        pkcsData=firebaseItems.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
        pkcsLocalBackup();
        if(pkcsSelectedId&&!pkcsData.some(x=>x.id===pkcsSelectedId))pkcsSelectedId=null;
        if(pkcsLockedId&&!pkcsData.some(x=>x.id===pkcsLockedId))pkcsLockedId=null;
        pkcsRender(false);
      },error=>{
        console.error(error);
        pkcsData=pkcsReadLocal()||[...pkcsDefaults];
        pkcsSelectedId=null;
        pkcsLockedId=null;
        pkcsRender(false);
        showToast("Gagal memuat PK dari Firebase");
      });
    }
    async function pkcsSaveFirebase(item){
      try{await pkCsDb.child(item.id).set(item);return true}
      catch(error){console.error(error);showToast("Gagal menyimpan PK ke Firebase");return false}
    }
    async function pkcsDeleteFirebase(id){
      try{await pkCsDb.child(id).remove();return true}
      catch(error){console.error(error);showToast("Gagal menghapus PK dari Firebase");return false}
    }
    function pkcsEscape(t){return String(t||"").replace(/[&<>"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]))}
    function pkcsNormalize(t){return String(t||"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}
    function pkcsGetMatches(query){
      const normalizedQuery=pkcsNormalize(query);
      const terms=normalizedQuery.split(/\s+/).filter(Boolean);
      if(!terms.length)return [];

      /*
        Pencarian hanya membaca JUDUL / KATA KUNCI.
        Isi template tidak ikut dicari agar hasil tidak menampilkan
        template lain yang kebetulan memiliki kata serupa di dalam isi.
      */
      return pkcsData.filter(item=>{
        const keyword=pkcsNormalize(item.keyword);
        return terms.every(term=>keyword.includes(term));
      }).sort((a,b)=>{
        const ak=pkcsNormalize(a.keyword);
        const bk=pkcsNormalize(b.keyword);

        const aExact=ak===normalizedQuery?0:1;
        const bExact=bk===normalizedQuery?0:1;
        if(aExact!==bExact)return aExact-bExact;

        const aStart=ak.startsWith(normalizedQuery)?0:1;
        const bStart=bk.startsWith(normalizedQuery)?0:1;
        if(aStart!==bStart)return aStart-bStart;

        const aIndex=ak.indexOf(normalizedQuery);
        const bIndex=bk.indexOf(normalizedQuery);
        if(aIndex!==bIndex)return aIndex-bIndex;

        return ak.localeCompare(bk,"id");
      });
    }
    function pkcsUpdateReadyBadge(){
      if(!pkcsReadyBadge)return;
      pkcsReadyBadge.textContent="DATA SIAP UNTUK DI COPY";
    }
    function pkcsRender(autoSelectTop=false){
      if(!pkcsList)return;
      const q=(pkcsSearchInput?.value||"").trim();
      if(!q){
        pkcsSelectedId=null;
        pkcsLockedId=null;
        pkcsList.innerHTML="";
        pkcsResult.textContent="Ketik kata kunci PK di kolom pencarian untuk menampilkan hasil.";
        pkcsResult.classList.add("pkcs-result-empty");
        pkcsUpdateReadyBadge();
        return;
      }

      const selected=pkcsLockedId?pkcsData.find(x=>x.id===pkcsLockedId):null;
      if(selected){
        pkcsSelectedId=selected.id;
        pkcsList.innerHTML="";
        pkcsResult.textContent=selected.content;
        pkcsResult.classList.remove("pkcs-result-empty");
        pkcsUpdateReadyBadge();
        return;
      }

      const shown=pkcsGetMatches(q);
      if(autoSelectTop||!shown.some(x=>x.id===pkcsSelectedId))pkcsSelectedId=shown[0]?.id||null;
      pkcsList.innerHTML=shown.length?shown.map(x=>`<button type="button" class="pkcs-item ${x.id===pkcsSelectedId?'active':''}" data-id="${x.id}">${pkcsEscape(x.keyword)}</button>`).join(""):`<div class="pkcs-empty">PK tidak ditemukan.<br>Tekan INPUT PK BARU untuk menambahkan.</div>`;
      const active=shown.find(x=>x.id===pkcsSelectedId)||shown[0];
      if(active){
        pkcsSelectedId=active.id;
        pkcsResult.textContent=active.content;
        pkcsResult.classList.remove("pkcs-result-empty");
      }else{
        pkcsSelectedId=null;
        pkcsResult.textContent="PK tidak ditemukan untuk kata kunci tersebut.";
        pkcsResult.classList.add("pkcs-result-empty");
      }
      pkcsUpdateReadyBadge();
    }
    function pkcsOpen(edit=false){const active=pkcsData.find(x=>x.id===pkcsSelectedId);pkcsEditId.value=edit&&active?active.id:"";pkcsKeywordInput.value=edit&&active?active.keyword:"";pkcsContentInput.value=edit&&active?active.content:"";pkcsModalTitle.textContent=edit?"Edit PK":"Input PK Baru";pkcsModal.classList.add("show");setTimeout(()=>pkcsKeywordInput.focus(),60)}
    function pkcsClose(){pkcsModal.classList.remove("show")}
