    const PKCS_SHEET_CSV_URL="https://docs.google.com/spreadsheets/d/1_EcGXsjxv_iMbk4Vyg8YimzQyj-ymayWe6nNS1ezHc8/gviz/tq?tqx=out:csv&gid=1081718576";
    function pkcsParseCsv(text){
      const rows=[];let row=[],cell="",quoted=false;
      for(let i=0;i<text.length;i++){
        const ch=text[i],next=text[i+1];
        if(ch==='"'&&quoted&&next==='"'){cell+='"';i++;continue}
        if(ch==='"'){quoted=!quoted;continue}
        if(ch===','&&!quoted){row.push(cell);cell="";continue}
        if((ch==='\n'||ch==='\r')&&!quoted){
          if(ch==='\r'&&next==='\n')i++;
          row.push(cell);cell="";
          if(row.some(v=>String(v).trim()!==""))rows.push(row);
          row=[];continue;
        }
        cell+=ch;
      }
      row.push(cell);if(row.some(v=>String(v).trim()!==""))rows.push(row);
      return rows;
    }
    async function pkcsImportGoogleSheet(){
      if(!pkcsImportSheetBtn)return;
      pkcsImportSheetBtn.disabled=true;
      pkcsImportSheetBtn.textContent="MENGAMBIL DATA...";
      if(pkcsImportStatus)pkcsImportStatus.textContent="Membaca kolom A dan B dari Google Sheet...";
      try{
        const response=await fetch(PKCS_SHEET_CSV_URL,{cache:"no-store"});
        if(!response.ok)throw new Error("HTTP "+response.status);
        const text=await response.text();
        const rows=pkcsParseCsv(text);
        const existingByKeyword=new Map(pkcsData.map(x=>[pkcsNormalize(x.keyword),x]));
        const updates={};let added=0,updated=0,skipped=0;
        rows.forEach((row,index)=>{
          const keyword=String(row[0]||"").trim();
          const content=String(row[1]||"").trim();
          if(!keyword||!content){skipped++;return}
          const normalized=pkcsNormalize(keyword);
          if(index===0&&(/kata.?kunci|keyword|judul/i.test(keyword))&&(/isi|content|pk/i.test(content))){skipped++;return}
          const old=existingByKeyword.get(normalized);
          const id=old?.id||("pk_sheet_"+Date.now()+"_"+index);
          updates[id]={id,keyword,content,updatedAt:Date.now()+index};
          if(old)updated++;else added++;
        });
        if(!Object.keys(updates).length)throw new Error("Tidak ada data valid pada kolom A dan B");
        await pkCsDb.update(updates);
        const msg=`Import selesai: ${added} baru, ${updated} diperbarui, ${skipped} dilewati.`;
        if(pkcsImportStatus)pkcsImportStatus.textContent=msg;
        showToast(msg);
      }catch(error){
        console.error(error);
        const msg="Import gagal. Pastikan Google Sheet dapat dilihat oleh siapa saja yang memiliki link dan tab PK memakai gid 1081718576.";
        if(pkcsImportStatus)pkcsImportStatus.textContent=msg;
        showToast("Gagal import Google Sheet");
      }finally{
        pkcsImportSheetBtn.disabled=false;
        pkcsImportSheetBtn.textContent="⇩ IMPORT GOOGLE SHEET";
      }
    }
    pkcsImportSheetBtn?.addEventListener("click",()=>{
      if(confirm("Import semua data kolom A sebagai kata kunci dan kolom B sebagai isi PK ke Firebase? Data dengan kata kunci sama akan diperbarui."))pkcsImportGoogleSheet();
    });
    function pkcsUpdateClock(){const d=new Date();const time=new Intl.DateTimeFormat("id-ID",{timeZone:"Asia/Jakarta",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}).format(d).replace(/\./g,":");const date=new Intl.DateTimeFormat("id-ID",{timeZone:"Asia/Jakarta",weekday:"long",day:"2-digit",month:"long",year:"numeric"}).format(d);const t=document.getElementById("pkcsClockTime"),dt=document.getElementById("pkcsClockDate");if(t)t.textContent=time;if(dt)dt.textContent=date;const parts=time.split(":").map(Number),h=parts[0]||0,m=parts[1]||0,s=parts[2]||0;const hour=document.querySelector(".pkx-clock-hand.hour"),minute=document.querySelector(".pkx-clock-hand.minute"),second=document.querySelector(".pkx-clock-hand.second");if(hour)hour.style.transform=`translateX(-50%) rotate(${(h%12)*30+m*.5}deg)`;if(minute)minute.style.transform=`translateX(-50%) rotate(${m*6+s*.1}deg)`;if(second)second.style.transform=`translateX(-50%) rotate(${s*6}deg)`}setInterval(pkcsUpdateClock,1000);pkcsUpdateClock();pkcsLoad();
